{
  "$schema": "https://open-design.ai/schemas/plugin.v1.json",
  "specVersion": "1.0.0",
  "name": "od-design-refine",
  "title": "Design refine",
  "title_i18n": {
    "en": "Design refine",
    "zh-CN": "设计精修",
    "zh-TW": "設計精修",
    "ja": "デザイン精緻化",
    "ko": "디자인 정교화",
    "de": "Design-Refinement",
    "fr": "Affinage de design",
    "ru": "Доводка дизайна",
    "es": "Refinamiento de diseño",
    "pt-BR": "Refino de design",
    "it": "Affinamento design",
    "vi": "Tinh chỉnh thiết kế",
    "pl": "Dopracowanie designu",
    "id": "Penyempurnaan desain",
    "nl": "Designverfijning",
    "ar": "تحسين التصميم",
    "tr": "Tasarım rafinajı",
    "uk": "Доопрацювання дизайну"
  },
  "version": "0.1.0",
  "publishedAt": "2026-05-12T14:39:32Z",
  "description": "Baseline Refine plugin for improving an existing OpenDesign artifact with a focused critique, small patch, and handoff summary.",
  "description_i18n": {
    "en": "Baseline Refine plugin for improving an existing OpenDesign artifact with a focused critique, small patch, and handoff summary.",
    "zh-CN": "基线 Refine 插件：用聚焦的批评、小补丁和交付摘要，改进现有 OpenDesign 产物。",
    "zh-TW": "基線 Refine 外掛：用聚焦的批評、小補丁和交付摘要，改進現有 OpenDesign 產物。",
    "ja": "既存の OpenDesign アーティファクトを集中したクリティーク、小さなパッチ、ハンドオフサマリーで改善するベースライン Refine プラグイン。",
    "ko": "기존 OpenDesign 산출물을 집중적인 비평, 작은 패치, 핸드오프 요약으로 개선하는 베이스라인 Refine 플러그인.",
    "de": "Baseline-Refine-Plugin: verbessert ein vorhandenes Open-Design-Artefakt mit fokussierter Kritik, kleinem Patch und Handoff-Zusammenfassung.",
    "fr": "Plugin Refine de base pour améliorer un artefact OpenDesign existant avec une critique ciblée, un petit patch et un résumé de handoff.",
    "ru": "Базовый Refine-плагин для улучшения существующего артефакта OpenDesign с помощью точечной критики, небольшого патча и сводки передачи.",
    "es": "Plugin Refine base para mejorar un artefacto existente de OpenDesign con una crítica enfocada, un parche pequeño y un resumen de handoff.",
    "pt-BR": "Plugin Refine base para melhorar um artefato existente do OpenDesign com crítica focada, patch pequeno e resumo de handoff.",
    "it": "Plugin Refine di base per migliorare un artefatto OpenDesign esistente con una critica mirata, una piccola patch e un riepilogo di handoff.",
    "vi": "Plugin Refine cơ sở: cải thiện artifact OpenDesign hiện có bằng phản biện tập trung, bản vá nhỏ và tóm tắt bàn giao.",
    "pl": "Bazowa wtyczka Refine: ulepsza istniejący artefakt OpenDesign dzięki skupionej krytyce, małej łatce i podsumowaniu handoff.",
    "id": "Plugin Refine dasar untuk memperbaiki artifact OpenDesign yang sudah ada dengan kritik fokus, patch kecil, dan ringkasan handoff.",
    "nl": "Basis-Refine-plug-in: verbetert een bestaand OpenDesign-artefact met gerichte kritiek, een kleine patch en een handoff-samenvatting.",
    "ar": "إضافة Refine الأساسية لتحسين عنصر OpenDesign قائم بنقد مركّز ورقعة صغيرة وملخص تسليم.",
    "tr": "Mevcut bir OpenDesign çıktısını odaklı eleştiri, küçük bir patch ve handoff özeti ile iyileştiren temel Refine eklentisi.",
    "uk": "Базовий плагін Refine для покращення наявного артефакту OpenDesign сфокусованою критикою, невеликим патчем і підсумком передачі."
  },
  "license": "MIT",
  "author": {
    "name": "OpenDesign",
    "url": "https://github.com/nexu-io"
  },
  "homepage": "https://github.com/nexu-io/open-design/tree/main/plugins/_official/scenarios/od-design-refine",
  "tags": [
    "scenario",
    "first-party",
    "refine",
    "tune",
    "review",
    "critique",
    "patch-edit"
  ],
  "compat": {
    "agentSkills": [
      {
        "path": "./SKILL.md"
      }
    ]
  },
  "od": {
    "kind": "scenario",
    "taskKind": "tune-collab",
    "scenario": "design-refine",
    "mode": "refine",
    "context": {
      "skills": [
        {
          "path": "./SKILL.md"
        }
      ]
    },
    "pipeline": {
      "stages": [
        {
          "id": "direction",
          "atoms": [
            "direction-picker"
          ]
        },
        {
          "id": "patch",
          "atoms": [
            "patch-edit"
          ]
        },
        {
          "id": "critique",
          "atoms": [
            "critique-theater"
          ],
          "repeat": true,
          "until": "critique.score>=4 || iterations>=3"
        },
        {
          "id": "handoff",
          "atoms": [
            "handoff"
          ]
        }
      ]
    },
    "capabilities": [
      "prompt:inject",
      "fs:read",
      "fs:write"
    ],
    "useCase": {
      "query": {
        "en": "Refine the existing artifact: {{refineGoal}}. Make the smallest useful design patch, critique it against the current design system, iterate until the score converges, then hand off the change summary.",
        "zh-CN": "优化当前产物：{{refineGoal}}。做一个最小但有效的设计改动，按当前设计系统进行 critique，迭代到评分收敛，然后输出改动交接摘要。"
      },
      "exampleOutputs": []
    },
    "inputs": [
      {
        "name": "refineGoal",
        "type": "string",
        "required": false,
        "label": "Refine goal",
        "placeholder": "make this landing page feel more premium and focused"
      },
      {
        "name": "direction",
        "type": "string",
        "required": false,
        "label": "Direction",
        "placeholder": "more editorial / more enterprise / more playful"
      }
    ]
  }
}
